// frontend/src/App.js
import React, { useState } from 'react';


function App() {
  const [question, setQuestion] = useState('');
  const [response, setResponse] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleAsk = async () => {
    setLoading(true);
    setError('');
    setResponse('');

    try {
      const res = await fetch('http://localhost:5000/ask', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ question }),
      });

      const data = await res.json();

      if (res.ok) {
        setResponse(data.answer);
      } else {
        setError(data.error || 'Something went wrong. Try again.');
      }
    } catch (err) {
      console.error('❌ Error in frontend:', err);
      setError('Failed to get a response. Try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: '2rem', fontFamily: 'Arial, sans-serif' }}>
      <h1>
        <span role="img" aria-label="brain">🧠</span> Ask the AI Assistant
      </h1>
      <textarea
        value={question}
        onChange={(e) => setQuestion(e.target.value)}
        placeholder="Type your question here..."
        rows="5"
        cols="60"
        style={{ fontSize: '16px', padding: '10px' }}
      />
      <br />
      <button onClick={handleAsk} disabled={loading} style={{ marginTop: '10px', padding: '8px 16px' }}>
        {loading ? 'Asking...' : 'Ask'}
      </button>

      <h3 style={{ marginTop: '20px' }}>Response:</h3>
      {error && <p style={{ color: 'red' }}>❌ {error}</p>}
      {response && <p style={{ color: 'green', whiteSpace: 'pre-wrap' }}>{response}</p>}
    </div>
  );
}

export default App;
